type State struct { Count int; Filter string }
type Action struct { Kind, Text string }
func reduce(s State, a Action) State {
    switch a.Kind {
    case "inc":
        n := s; n.Count++; return n
    case "filter":
        n := s; n.Filter = a.Text; return n
    }
    return s // unhandled action: same state, no copy
}
